```python
def can_move_rook(board, rook):
    row, col = rook
    for i in range(len(board)):
        if board[i][col] == 1:
            return False
    for j in range(len(board[0])):
        if board[row][j] == 1:
            return False
    return True

def move_rook(board, rook, new_row, new_col):
    board[rook[0]][rook[1]] = 0
    board[new_row][new_col] = 1
    return board

def is_possible_to_move(board, rooks):
    for i in range(len(rooks)):
        if not can_move_rook(board, rooks[i]):
            return False
    return True

def solve():
